{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.BUILDSKILL_DB_PRODUCT_MARKETING_CONSOLIDATED AS WITH sku_map AS ( SELECT * FROM `maplemonk.Buildskill_GS_SKU_MASTER` QUALIFY ROW_NUMBER() OVER (PARTITION BY master_sku) = 1 ), marketing_consolidated AS ( SELECT LOWER(TRIM(channel)) AS channel, DATE(date) AS date, SUM(CAST(spend AS FLOAT64)) AS total_channel_spend FROM `maplemonk.buildskill_wh_MARKETING_CONSOLIDATED` GROUP BY 1,2 ), amazon_channel_spend AS ( SELECT LOWER(\'amazon\') AS channel, DATE(date) AS date, SUM(CAST(spend AS FLOAT64)) AS total_channel_spend FROM `maplemonk.Buildskill_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED` GROUP BY 1,2 ), vendor_sales AS ( SELECT TRIM(asin) AS asin, DATE(startTime) AS sales_date, SUM(IFNULL(Ordered_Revenue,0)) AS sales, SUM(IFNULL(ordered_units,0)) AS total_quantity FROM `maplemonk.Buildskill_AMAZON_VENDOR_PARTNER_SALES` GROUP BY 1,2 ), amazon AS ( SELECT CAST(a.channel_product_id AS STRING) AS PRODUCT_ID, CAST(NULL AS STRING) AS VARIANT_ID, a.DATE AS DATE, FORMAT_DATE(\'%A\', a.DATE) AS DAY_OF_WEEK, EXTRACT(YEAR FROM a.DATE) AS YEAR, EXTRACT(MONTH FROM a.DATE) AS MONTH, CAST(\'Amazon\' AS STRING) AS CHANNEL, CAST(null AS STRING) AS ACCOUNT, a.clicks AS CLICKS, a.spend AS SPEND, a.impressions AS IMPRESSIONS, a.conversions AS CONVERSIONS, a.CONVERSION_VALUE as CONVERSION_VALUE, IFNULL(vs.sales,0) AS sales, IFNULL(vs.total_quantity,0) AS total_quantity, UPPER(TRIM(sm.master_sku)) AS SKU, UPPER(TRIM(sm.PRODUCT_TITLE)) as product_name, CONCAT(upper(trim(CATEGORY)), \' \', upper(trim(SUB_CATEGORY))) AS master_category FROM ( SELECT COALESCE( CASE WHEN LENGTH(TRIM(am.asin)) = 10 THEN TRIM(am.asin) END, CASE WHEN LENGTH(TRIM(SPLIT(am.campaignname,\'-\')[SAFE_OFFSET(2)])) = 10 THEN TRIM(SPLIT(am.campaignname,\'-\')[SAFE_OFFSET(2)]) END ) AS channel_product_id, DATE(am.date) AS date, SUM(IFNULL(clicks,0)) AS clicks, SUM(IFNULL(spend,0)) AS spend, SUM(IFNULL(impressions,0)) AS impressions, SUM(IFNULL(am.ATTRIBUTED_CONVERSIONS_14D,0)) AS conversions, SUM(IFNULL(am.ATTRIBUTED_SALES_14D,0)) AS conversion_value FROM `maplemonk.Buildskill_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED` am WHERE COALESCE( CASE WHEN LENGTH(TRIM(am.asin)) = 10 THEN TRIM(am.asin) END, CASE WHEN LENGTH(TRIM(SPLIT(am.campaignname,\'-\')[SAFE_OFFSET(2)])) = 10 THEN TRIM(SPLIT(am.campaignname,\'-\')[SAFE_OFFSET(2)]) END) IS NOT NULL GROUP BY 1,2) a LEFT JOIN sku_map sm ON TRIM(LOWER(CAST(a.channel_product_id AS STRING))) = TRIM(LOWER(CAST(sm.ASIN AS STRING))) LEFT JOIN vendor_sales vs ON TRIM(a.channel_product_id) = TRIM(vs.asin) AND a.date = vs.sales_date ), marketing_consolidated_product_intermediate AS ( SELECT * FROM amazon ), category_monthly_sales AS ( SELECT master_category, DATE_TRUNC(DATE, MONTH) AS sales_month, SUM(IFNULL(sales,0)) AS monthly_sales FROM marketing_consolidated_product_intermediate GROUP BY 1,2 ), category_past_benchmark AS ( SELECT master_category, sales_month, MAX(monthly_sales) OVER (PARTITION BY master_category ORDER BY sales_month ROWS BETWEEN 11 PRECEDING AND CURRENT ROW) AS past_benchmark FROM category_monthly_sales ) SELECT m.*, mcm.owner AS owner, IFNULL(SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL), 0) AS total_product_lvl_spend, IFNULL(CASE WHEN LOWER(m.channel) LIKE \'%amazon%\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END, 0) AS total_channel_spend, IFNULL(CASE WHEN LOWER(m.channel) LIKE \'%amazon%\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END, 0) - IFNULL(SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL), 0) AS spend_diff, CASE WHEN (CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) > SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL) AND SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL) > 0 THEN ((CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) - SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL)) * (m.conversion_value / SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL)) ELSE 0 END AS allocated_spend_diff, CASE WHEN (CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) > SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL) AND SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL) > 0 THEN m.SPEND + (((CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) - SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL)) * (m.conversion_value / SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL))) ELSE m.SPEND END AS corrected_spend, IFNULL(cpb.past_benchmark,0) AS past_benchmark, IFNULL(CAST(REPLACE(st.target, \',\', \'\') AS FLOAT64),0) AS monthly_target, CAST(REPLACE(att.ASIN_level_Ads_Spends, \'%\', \'\') AS FLOAT64) as ntacos_target FROM marketing_consolidated_product_intermediate m LEFT JOIN marketing_consolidated mc ON LOWER(TRIM(CAST(m.channel AS STRING))) = LOWER(TRIM(CAST(mc.channel AS STRING))) AND CAST(m.date AS DATE) = CAST(mc.date AS DATE) LEFT JOIN amazon_channel_spend ac ON LOWER(TRIM(CAST(m.channel AS STRING))) = LOWER(TRIM(CAST(ac.channel AS STRING))) AND CAST(m.date AS DATE) = CAST(ac.date AS DATE) LEFT JOIN category_past_benchmark cpb ON m.master_category = cpb.master_category AND DATE_TRUNC(m.DATE, MONTH) = cpb.sales_month LEFT JOIN `maplemonk.Buildskill_GS_SKU_Target` st ON UPPER(TRIM(m.sku)) = UPPER(TRIM(st.sku)) AND UPPER(TRIM(st.month)) = UPPER(FORMAT_DATE(\'%B\', m.date)) LEFT JOIN `maplemonk.Buildskill_GS_Master_Category_Mapping` mcm ON UPPER(TRIM(m.master_category)) = UPPER(TRIM(mcm.master_category)) left join `maplemonk.Buildskill_GS_Amazon_Tacos_Target` att on trim(m.PRODUCT_ID) = trim(att.asin) and UPPER(TRIM(m.master_category)) = UPPER(TRIM(att.PL)) ; CREATE OR REPLACE TABLE MAPLEMONK.BUILDSKILL_CATEGORY_DAILY_SUMMARY AS SELECT DATE, DATE_TRUNC(DATE, MONTH) AS month_start, master_category, product_id, product_name, owner, SUM(IFNULL(sales,0)) AS daily_sales, SUM(IFNULL(corrected_spend,0)) AS daily_spend, SUM(IFNULL(conversion_value,0)) AS daily_paid_sales, MAX(IFNULL(past_benchmark,0)) AS past_benchmark, MAX(IFNULL(monthly_target,0)) AS monthly_target, SUM(IFNULL(conversions,0)) AS daily_ad_orders, SUM(IFNULL(total_quantity,0)) AS total_quantity, SUM(IFNULL(clicks,0)) AS daily_clicks, SAFE_DIVIDE(SUM(IFNULL(sales,0) * IFNULL(ntacos_target,0)), SUM(IFNULL(sales,0))) AS daily_ntacos_target FROM MAPLEMONK.BUILDSKILL_DB_PRODUCT_MARKETING_CONSOLIDATED GROUP BY 1,2,3,4,5,6; CREATE OR REPLACE TABLE MAPLEMONK.BUILDSKILL_CATEGORY_MONTHLY_SUMMARY AS SELECT owner, month_start, master_category, product_id, product_name, MAX(past_benchmark) AS past_benchmark, MAX(monthly_target) AS monthly_target, SUM(daily_sales) AS total_sales, SUM(daily_spend) AS total_spend, SUM(daily_paid_sales) AS paid_sales, SAFE_DIVIDE(SUM(daily_spend), SUM(daily_sales)) AS tacos, SAFE_DIVIDE(SUM(daily_spend), SUM(daily_paid_sales)) AS acos, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_sales ELSE 0 END) AS w1_nmv, MAX(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_sales END) AS w1_trending, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_spend ELSE 0 END) AS w1_spend, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN daily_paid_sales ELSE 0 END) AS w1_paid_sales, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 1 AND 7 THEN total_quantity ELSE 0 END) AS w1_total_quantity, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_sales ELSE 0 END) AS w2_nmv, MAX(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_sales END) AS w2_trending, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_spend ELSE 0 END) AS w2_spend, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN daily_paid_sales ELSE 0 END) AS w2_paid_sales, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 8 AND 14 THEN total_quantity ELSE 0 END) AS w2_total_quantity, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_sales ELSE 0 END) AS w3_nmv, MAX(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_sales END) AS w3_trending, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_spend ELSE 0 END) AS w3_spend, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN daily_paid_sales ELSE 0 END) AS w3_paid_sales, SUM(CASE WHEN EXTRACT(DAY FROM DATE) BETWEEN 15 AND 21 THEN total_quantity ELSE 0 END) AS w3_total_quantity, SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_sales ELSE 0 END) AS w4_nmv, MAX(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_sales END) AS w4_trending, SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_spend ELSE 0 END) AS w4_spend, SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN daily_paid_sales ELSE 0 END) AS w4_paid_sales, SUM(CASE WHEN EXTRACT(DAY FROM DATE) >= 22 THEN total_quantity ELSE 0 END) AS w4_total_quantity, SUM(daily_ad_orders) AS ad_orders, SUM(total_quantity) AS total_orders, SUM(daily_clicks) AS clicks, SAFE_DIVIDE(SUM(daily_ntacos_target * daily_sales), SUM(daily_sales)) AS ntacos_target FROM maplemonk.BUILDSKILL_CATEGORY_DAILY_SUMMARY GROUP BY 1,2,3,4,5;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            